public List<Order> findAll(OrderSearch search) {
    return queryFactory
            .select(order)
            .from(order)
            .join(order.member, member)
            .where(statusEq(search.getOrderStatus()),
                   nameLike(search.getMemberName()))
            .limit(1000)
            .fetch();
}

private BooleanExpression statusEq(OrderStatus statusCond) {
    return statusCond == null ? null : order.status.eq(statusCond);
}

private BooleanExpression nameLike(String nameCond) {
    return StringUtils.hasText(nameCond) ? member.name.like(nameCond) : null;
}
